check "release shopfront is deployed with chart shopfront-1.1.0" bash -c "helm --kube-context main -n web-shop list -o json 2>/dev/null | grep -q '\"name\":\"shopfront\".*\"status\":\"deployed\".*\"chart\":\"shopfront-1.1.0\"'"
check "previous values kept (3 replicas, banner, currency)" bash -c "[ \"\$(kubectl --context main -n web-shop get cm shopfront-settings -o jsonpath='{.data.banner}|{.data.currency}|{.data.chartVersion}')\" = 'Black Friday|CHF|1.1.0' ] && deploy_ready main shopfront web-shop 3"
check "pods carry the label team=storefront" bash -c "[ \"\$(kubectl --context main -n web-shop get deploy shopfront -o jsonpath='{.spec.template.metadata.labels.team}')\" = storefront ] && [ \"\$(kubectl --context main -n web-shop get deploy shopfront -o jsonpath='{.status.updatedReplicas}')\" = 3 ]"
check "revision number written" bash -c "file_eq '$ANSWERS/shopfront-revision.txt' \"\$(helm --kube-context main -n web-shop history shopfront --max 1 -o json | sed -n 's/.*\"revision\":\([0-9]*\).*/\1/p')\""
